import 'package:flutter/material.dart';

import 'theme.dart';

/// The Vinylss logo: a record with a "V" on its amber label.
///
/// Generated by tool/branding/generate.py.
class VinylssLogo extends StatelessWidget {
  const VinylssLogo({super.key, this.size = 128});

  final double size;

  @override
  Widget build(BuildContext context) => Image.asset(
        'assets/branding/logo.png',
        width: size,
        height: size,
        filterQuality: FilterQuality.medium,
        semanticLabel: 'Vinylss',
      );
}

/// Startup screen that continues the native launch splash: the logo stays where the
/// native one drew it (centred, 128 px) and the name fades in below it.
class BrandSplash extends StatelessWidget {
  const BrandSplash({super.key});

  static const _logoSize = 128.0;

  @override
  Widget build(BuildContext context) {
    return SizedBox.expand(
      child: ColoredBox(
        color: Palette.background,
        child: Stack(alignment: Alignment.center, children: [
          const VinylssLogo(size: _logoSize),
          Padding(
            padding: const EdgeInsets.only(top: _logoSize + 72),
            child: TweenAnimationBuilder<double>(
              tween: Tween(begin: 0, end: 1),
              duration: const Duration(milliseconds: 900),
              curve: const Interval(0.3, 1, curve: Curves.easeOut),
              builder: (context, t, child) => Opacity(
                opacity: t,
                child: Transform.translate(offset: Offset(0, 8 * (1 - t)), child: child),
              ),
              child: Text('Vinylss', style: Theme.of(context).textTheme.headlineMedium),
            ),
          ),
        ]),
      ),
    );
  }
}
